import { sql } from "drizzle-orm";
import { z } from "zod";

import { newId } from "@/lib/uuid";

import { runCommand, type CommandOptions } from "../run";
import { adminBaseSchema, writeAdminAudit } from "./shared";

function rowsFrom(result: unknown): Array<Record<string, unknown>> {
  return (result as { rows?: Array<Record<string, unknown>> }).rows ?? [];
}

const deviceKeySchema = z.string().trim().min(1).max(128);

const rotateSchema = z.object({
  ...adminBaseSchema,
  deviceKey: deviceKeySchema,
  /**
   * The raw token is generated by the API layer and never stored. Only its
   * SHA-256 hash reaches this command, so command logs cannot leak a credential.
   */
  tokenHash: z.string().regex(/^[a-f0-9]{64}$/, "Invalid token hash"),
  expiresAt: z.iso.datetime().optional(),
});
export type RotateFacilitySyncTokenInput = z.input<typeof rotateSchema>;

/** Cloud-only: replace a facility/device sync token without exposing the secret in logs. */
export async function rotateFacilitySyncToken(
  input: RotateFacilitySyncTokenInput,
  options: CommandOptions = {},
) {
  const values = rotateSchema.parse(input);
  const id = newId();
  const expiresAt = values.expiresAt ?? new Date(Date.now() + 90 * 24 * 60 * 60 * 1000).toISOString();

  return runCommand(
    { facilityId: values.facilityId, idempotencyKey: values.idempotencyKey },
    "rotateFacilitySyncToken",
    async (tx) => {
      const rotated = await tx.execute(sql`
        INSERT INTO facility_sync_tokens (
          id, facility_id, device_key, token_hash, active, created_at,
          last_used_at, expires_at, revoked_at
        )
        VALUES (
          ${id}::uuid, ${values.facilityId}::uuid, ${values.deviceKey}, ${values.tokenHash},
          true, now(), NULL, ${expiresAt}::timestamptz, NULL
        )
        ON CONFLICT (facility_id, device_key) DO UPDATE SET
          token_hash = EXCLUDED.token_hash,
          active = true,
          created_at = now(),
          last_used_at = NULL,
          expires_at = EXCLUDED.expires_at,
          revoked_at = NULL
        RETURNING id::text AS "tokenId"
      `);
      const tokenId = String(rowsFrom(rotated)[0]?.tokenId ?? id);

      await writeAdminAudit(tx, {
        facilityId: values.facilityId,
        actor: values.actor,
        action: "admin.sync.token.rotate",
        entity: "facility_sync_tokens",
        entityId: tokenId,
        details: {
          deviceKey: values.deviceKey,
          expiresAt,
        },
      });

      return { tokenId, expiresAt };
    },
    { ...options, allowCrossAuthority: true },
  );
}

const revokeSchema = z.object({
  ...adminBaseSchema,
  deviceKey: deviceKeySchema,
});
export type RevokeFacilitySyncTokenInput = z.input<typeof revokeSchema>;

/** Cloud-only: immediately revoke a facility/device sync token. */
export async function revokeFacilitySyncToken(
  input: RevokeFacilitySyncTokenInput,
  options: CommandOptions = {},
) {
  const values = revokeSchema.parse(input);

  return runCommand(
    { facilityId: values.facilityId, idempotencyKey: values.idempotencyKey },
    "revokeFacilitySyncToken",
    async (tx) => {
      const result = await tx.execute(sql`
        UPDATE facility_sync_tokens
        SET active = false, revoked_at = now()
        WHERE facility_id = ${values.facilityId}::uuid
          AND device_key = ${values.deviceKey}
          AND revoked_at IS NULL
      `);

      await writeAdminAudit(tx, {
        facilityId: values.facilityId,
        actor: values.actor,
        action: "admin.sync.token.revoke",
        entity: "facility_sync_tokens",
        entityId: values.facilityId,
        details: { deviceKey: values.deviceKey },
      });

      return { revoked: (result as { rowCount?: number }).rowCount ?? 0 };
    },
    { ...options, allowCrossAuthority: true },
  );
}
